B.aQX=new A.cc([0,"\ud5c8\ud5c8, \ub299\uc740 \ubab8\uc774 \uc7ac \ubc14\ub78c \ud55c \ubc88\uc5d0 \uc774 \uaf34\uc774\uad6c\uba3c. \ud558\ub8e8\uba74 \ub41c\ub2e4\uace0.",1,"\uc774 \uc815\ub3c4\ub294 \ubc30\ub2ec\ud558\ub2e4 \ub118\uc5b4\uc9c4 \uac70\uc5d0 \ube44\ud558\uba74 \uc544\ubb34\uac83\ub3c4 \uc544\ub2c8\uc5d0\uc694.",2,"\uc81c\uac00 \uc81c\uc77c \uc798 \uc54c\uc544\uc694. \ud558\ub8e8\uba74 \ub3fc\uc694. \ubd95\ub300\ub294 \uc81c\uac00 \uac10\uc744\uac8c\uc694.",3,"\u2026\ud558\ub098\ub3c4 \uc548 \uc544\ud30c\uc694. \uc9c4\uc9dc\uc608\uc694. \u2026\uc870\uae08\ub9cc \uc544\ud30c\uc694.",4,"\uc544\uc774\uace0, \uc774 \ud560\ubbf8 \uac71\uc815\uc740 \ub9c8\ub798\uc774. \ud558\ub8e8 \ub204\ubc84 \uc788\uc73c\ubbc4 \ub41c\ub2e4.",5,"\ub0b4 \uac71\uc815 \ub9d0\uace0 \uad6d\uc1a5\uc774\ub098 \ubd10. \ub0b4\uc77c\uc740 \ub0b4\uac00 \ub2e4\uc2dc \ub053\uc778\ub2e4.",6,"\u2026\uad1c\ucc2e\ub2e4\ub2c8\uae4c. \ubc29\ubcbd\uc740 \ub0b4\uc77c \ub0b4\uac00 \ub2e4\uc2dc \uc138\uc6b8\uac8c.",7,"\u2026\uad1c\ucc2e\uc544\uc694. \uc624\ub978\uc190\uc740 \uba40\uca61\ud558\ub2c8\uae4c \uadf8\ub9bc\uc740 \uadf8\ub9b4 \uc218 \uc788\uc5b4\uc694.",8,"\ubcc4\uac70 \uc544\ub2c8\uc5d0\uc694. \ub0b4\uc77c\uc774\uba74 \ub2e4\uc2dc \ub098\uac00\uc694.",9,"\u2026\uc774\ubc88\uc5d4 \ub3c4\ub9dd\uce58\uc9c0 \uc54a\uc558\uc5b4\uc694. \uadf8\uac70\uba74 \ub410\uc5b4\uc694.",10,"\uc624\ub298 \ubc24 \ubc29\uc1a1\uc740 \uc26c\uc5b4\uc57c\uaca0\ub124\uc694. \ubaa9\uc18c\ub9ac\ub294 \uba40\uca61\ud55c\ub370, \ud314\uc774 \ub9d0\uc744 \uc548 \ub4e4\uc5b4\uc11c\uc694.",11,"\ub0b4\uc77c \uc608\ubcf4\ub294 \ub204\uc6cc\uc11c \ud560\uac8c\uc694. \ub9d1\uc74c, \uc774\ubc88\uc5d4 \uc815\ub9d0\ub85c\uc694.",12,"\uc774 \ub299\uc740\uc774 \ud0dc\uc5fd\uc774 \uc880 \ud480\ub838\uc744 \ubfd0\uc77c\uc138. \ud558\ub8e8\uba74 \ub2e4\uc2dc \uac10\uae30\uaca0\uc9c0.",13,"\u2026\ubc84\ud2f8 \ub9cc\ud574\uc694. \uc790\ub9ac\ub97c \uc9c0\ud0a8 \uac12\uc774\ub2c8\uae4c\uc694.",14,"\uc57d\ucd08\ub294 \uc81c\uac00 \uc54c\uc544\uc694. \ud558\ub8e8\uba74 \uc544\ubb3c \uac70\uc608\uc694.",15,"\u2026\uc6a9\uc811\ud558\ub2e4 \ub374 \uac83\ubcf4\ub2e4 \ub0ab\ub124. \ud558\ub8e8\uba74 \ub3fc.",16,"\uad6c\uc870\ub300\uac00 \uad6c\uc870\ubc1b\ub294 \uc2e0\uc138\ub124\uc694. \ud558\ub8e8\ub9cc \uc274\uac8c\uc694.",17,"\u2026\ubcc4\uac70 \uc544\ub2c8\uc57c. \uae4c\ub9c8\uadc0 \ub550 \uc774\ubcf4\ub2e4 \ub354\ud55c \uac83\ub3c4 \ud63c\uc790 \ubc84\ud17c\uc5b4."],t.TM)
