B.aKh=new A.b(B.ee,["\u201c\uc7a5\uc791\uc774 \ubaa8\uc790\ub77c\uad6c\uba3c. \uc624\ub298 \ubc24 \ubd88 \uc880 \ub109\ub109\ud788 \ub54c \ubcf4\uc790\uace0.\u201d","\u201c\uace0\ucca0\ub9cc \uc788\uc73c\uba74 \uc774\uac83\uc800\uac83 \uc190\ubcfc \uc218 \uc788\uad6c\uba3c. \ub179\uc2a8 \uac70\ub77c\ub3c4 \uc8fc\uc6cc \uc640.\u201d","\u201c\ucc3d\uace0\uac00 \ube44\uc5b4 \uac00\ub294\uad6c\uba3c. \uc560\ub4e4 \uba39\uc744 \uac70\ub77c\ub3c4 \ucc44\uc6cc \ub450\uc790\uace0.\u201d","\u201c\uc9c0\ubd95\uc5d0 \uad6c\uba4d\uc774 \ub0ac\uad6c\uba3c. \ucca0\ud310\uc73c\ub85c \ub36e\uc790\uace0.\u201d","\u201c\ube68\ub7ab\uc904\uc774 \ub04a\uc5b4\uc84c\uad6c\uba3c. \ubc27\uc904 \uc880 \uaf2c\uc544 \uc918.\u201d","\u201c\uc800 \ub108\uba38\uc5d0 \ubb50\uac00 \uc788\ub294\uc9c0 \uad81\uae08\ud558\uad6c\uba3c. \uc870\uae08\ub9cc \ub354 \ubc1d\ud600 \ubcf4\uc790\uace0.\u201d","\u201c\uc9c0\ub3c4\uc5d0 \ud45c\uc2dc\ud574 \ub454 \ub370\uac00 \uc788\uad6c\uba3c. \ub204\uac00 \ud55c \ubc88 \ub2e4\ub140\uc640 \uc918.\u201d","\u201c\uc9c0\ud558\ucca0\uc5ed \ub9e4\uc810\uc5d0 \ud1b5\uc870\ub9bc\uc774 \ub0a8\uc558\uc744\uc9c0\ub3c4 \ubaa8\ub974\uaca0\uad6c\uba3c. \ud55c\ubc88 \ub0b4\ub824\uac00 \ubcf4\uc790\uace0.\u201d","\u201c\ub77c\ub514\uc624\uc5d0\uc11c \ub204\uac00 \ubd80\ub974\ub294 \uac83 \uac19\uad6c\uba3c. \ub2e4\uc774\uc5bc \uc880 \ub3cc\ub824 \ubd10.\u201d","\u201c\ub2e4\ub4e4 \ub9d0\uc740 \uc548 \ud574\ub3c4 \ubd80\ud0c1\uc774 \ud558\ub098\uc529 \uc788\ub294 \ub208\uce58\uad6c\uba3c.\u201d","\u201c\uc624\ub298 \ubc24\ub3c4 \ubb34\uc0ac\ud788 \ub118\uae30\uc790\uace0. \uc544\uce68\uc5d0 \ucc28 \ud55c\uc794\ud558\uba74\uc11c \uc6c3\uc790\uace0.\u201d","\u201c\uc694\uc0c8 \ub2e4\ub4e4 \uc9c0\ucce4\uad6c\uba3c. \uc794\uce58 \ud55c\ubc88 \uc5f4\uc790\uace0.\u201d"],t.w)
B.aKj=new A.b(B.ee,["\u201c\uc7a5\uc791\uc774 \ubaa8\uc790\ub77c\uc694. \uc624\ub298 \ubc24 \ucd94\uc6b0\uba74 \uc548 \ub418\uc796\uc544\uc694!\u201d","\u201c\uace0\ucca0 \uc8fc\uc6b0\ub7ec \uac00\uc694! \ubc18\uc9dd\uc774\ub294 \uac70 \uc81c\uac00 \uba3c\uc800 \ucc3e\uc744\uac8c\uc694.\u201d","\u201c\ucc3d\uace0\uc5d0 \uba39\uc744 \uac8c \ubcc4\ub85c \uc5c6\uc5b4\uc694. \uac19\uc774 \ucc3e\uc73c\ub7ec \uac00\uc694!\u201d","\u201c\uc9c0\ubd95\uc5d0 \uad6c\uba4d\uc774 \ub0ac\uc5b4\uc694. \ucca0\ud310\uc73c\ub85c \ub9c9\uc544 \uc8fc\uc138\uc694!\u201d","\u201c\ube68\ub7ab\uc904\uc774 \ub04a\uc5b4\uc84c\uc5b4\uc694. \ubc27\uc904 \uaf2c\uc544 \uc8fc\uc138\uc694!\u201d","\u201c\uc800 \ub108\uba38\uc5d0 \ubb50\uac00 \uc788\uc744\uae4c\uc694? \uc870\uae08\ub9cc \ub354 \ubc1d\ud600 \ubd10\uc694!\u201d","\u201c\uba40\ub9ac\uc11c \uc5f0\uae30\uac00 \ub098\uc694. \ub204\uac00 \uc788\ub098 \ubd10\uc694. \uac00 \ubd10\uc694!\u201d","\u201c\uc9c0\ud558\uc5d0\uc11c \uc774\uc0c1\ud55c \uc18c\ub9ac\uac00 \ub0ac\ub300\uc694. \u2026\uac19\uc774 \ub0b4\ub824\uac00 \uc904 \uac70\uc8e0?\u201d","\u201c\ub77c\ub514\uc624\uc5d0\uc11c \ub204\uac00 \ubd80\ub974\ub294 \uac83 \uac19\uc558\uc5b4\uc694! \ub2e4\uc774\uc5bc \ub3cc\ub824 \ubd10\uc694.\u201d","\u201c\ub2e4\ub4e4 \ubd80\ud0c1\uc774 \ud558\ub098\uc529 \uc788\ub300\uc694. \uc81c\uac00 \ub2e4 \ub4e4\uc5c8\uc5b4\uc694!\u201d","\u201c\uc624\ub298 \ubc24\ub3c4 \ubb34\uc0ac\ud788 \ub118\uaca8\uc694. \uadf8\ub7fc \ubd88\ube5b \uac19\uc774 \uc138\uc5b4\uc694!\u201d","\u201c\ub2e4\ub4e4 \ud798\ub4e4\uc5b4 \ubcf4\uc5ec\uc694. \uc794\uce58 \uc5f4\uc5b4\uc694, \ub124?\u201d"],t.w)
B.aKl=new A.b(B.ee,["\u201c\uc7a5\uc791\uc774 \ubaa8\uc790\ub780\ub2e4. \uc624\ub298 \ubc24 \ubd88 \uc880 \ub109\ub109\ud788 \ub54c \ubcf4\uc790\uc774.\u201d","\u201c\uc1e0\ubd99\uc774 \uc880 \ubaa8\uc544 \uc624\uc774\uc18c. \ub179\uc2a8 \uac70\ub77c\ub3c4 \ub2e4 \uc4f8 \ub370\uac00 \uc788\ub370\uc774.\u201d","\u201c\ucc3d\uace0\uac00 \ube44\uc5b4 \uac04\ub2e4. \uc544\uc774\ub4e4 \ubb35\uc744 \uac70\ub77c\ub3c4 \ucc44\uc6cc \ub193\uc790.\u201d","\u201c\uc9c0\ubd95\uc5d0 \uad6c\uba4d\uc774 \ub0ac\ub370\uc774. \ucca0\ud310\uc73c\ub85c \ub36e\uc5b4\uc57c \uc548 \ub418\uaca0\ub098.\u201d","\u201c\ube68\ub7ab\uc904\uc774 \ub04a\uc5b4\uc84c\ub370\uc774. \ubc27\uc904 \uc880 \uaf2c\uc544 \uc8fc\uaca0\ub098?\u201d","\u201c\uc800 \ub108\uba38\uc5d0 \ubb50\uac00 \uc788\ub294\uace0 \uad81\uae08\ud558\ub370\uc774. \ucabc\ub9e4\ub9cc \ub354 \ubc1d\ud600 \ub3c4.\u201d","\u201c\uba40\ub9ac\uc11c \uc5f0\uae30\uac00 \uc62c\ub77c\uc628\ub2e4. \ub204\uac00 \ucacc \uac00 \ubd10\uc57c \uc548 \ub418\uaca0\ub098.\u201d","\u201c\uc9c0\ud558\ucca0\uc5ed \ub9e4\uc810\uc5d0 \ud1b5\uc870\ub9bc\uc774 \ub0a8\uc544 \uc788\uc744\uc9c0\ub3c4 \ubaa8\ub978\ub370\uc774. \ud55c\ubc88 \ub0b4\ub824\uac00 \ubcf4\uc774\uc18c.\u201d","\u201c\ub77c\ub514\uc624\uc5d0\uc11c \ub204\uac00 \ubd80\ub974\ub294 \uac70 \uac19\ub354\ub77c. \ub2e4\uc774\uc5bc \uc880 \ub3cc\ub824 \ubcf4\uc774\uc18c.\u201d","\u201c\ub2e4\ub4e4 \ub9d0\uc740 \uc548 \ud574\ub3c4 \ubd80\ud0c1\uc774 \ud558\ub098\uc529 \uc788\uc744 \ub07c\ub2e4.\u201d","\u201c\uc624\ub298 \ubc24\ub3c4 \ubb34\uc0ac\ud788 \ub118\uae30\uc81c\uc774. \uadf8\ub77c\ubbc4 \ub530\uc21c \uad6d \ud55c \uadf8\ub987 \ud558\uc790.\u201d","\u201c\uc694\uc0c8 \ub2e4\ub4e4 \uc9c0\ucce4\ub370\uc774. \uc794\uce58 \ud55c\ubc88 \uc5f4\uc790.\u201d"],t.w)
B.aKm=new A.b(B.ee,["\u201c\uc7a5\uc791 \ub5a8\uc5b4\uc838 \uac04\ub2e4. \uad6d\uc1a5 \ubd88 \uaebc\uc9c0\uae30 \uc804\uc5d0 \ub098\ubb34 \uc880 \ud574 \uc640.\u201d","\u201c\uace0\ucca0 \uc880 \uc8fc\uc6cc \uc640. \uc1a5 \ubc1b\uce68\uc774 \ub2e4 \uc0ad\uc558\uc5b4.\u201d","\u201c\ucc3d\uace0 \ube44\uc5b4 \uac04\ub2e4. \uc560\ub4e4 \uba39\uc744 \uac70\ub77c\ub3c4 \ucc44\uc6cc \ub194, \uad6d \ub053\uc774\uac8c.\u201d","\u201c\uc9c0\ubd95 \uc0c8\ub294 \uac70 \ubd24\uc9c0? \ucca0\ud310 \uc880 \ub9cc\ub4e4\uc5b4. \uad6d\uc5d0 \uc7ac \ub4e4\uc5b4\uac00.\u201d","\u201c\ube68\ub7ab\uc904 \ub04a\uc5b4\uc84c\uc5b4. \ubc27\uc904 \uc880 \uaf2c\uc544 \uc640, \uc55e\uce58\ub9c8 \ub9d0\ub824\uc57c \ub3fc.\u201d","\u201c\uc800 \ub108\uba38 \uc880 \ubc1d\ud600 \ubd10. \uc7a5 \ubcfc \ub370\uac00 \uc788\uc744\uc9c0 \ub204\uac00 \uc54c\uc544.\u201d","\u201c\uba40\ub9ac\uc11c \uc5f0\uae30 \uc62c\ub77c\uc624\ub354\ub77c. \ub204\uac00 \uac00 \ubd10. \ubc25\uc740 \uba39\uace0 \uac00\uace0.\u201d","\u201c\uc9c0\ud558\ucca0\uc5ed \ub9e4\uc810\uc5d0 \ud1b5\uc870\ub9bc \ub0a8\uc558\uc744\uc9c0 \ubab0\ub77c. \ub0b4\ub824\uac00 \ubd10.\u201d","\u201c\ub77c\ub514\uc624\uc5d0\uc11c \ub204\uac00 \ubd80\ub974\ub294 \uac83 \uac19\ub354\ub77c. \ub2e4\uc774\uc5bc \uc880 \ub3cc\ub824 \ubd10.\u201d","\u201c\ub2e4\ub4e4 \ub9d0 \uc548 \ud574\ub3c4 \ubd80\ud0c1 \ud558\ub098\uc529\uc740 \uc788\uc5b4. \ub4e4\uc5b4 \uc918.\u201d","\u201c\uc624\ub298 \ubc24\ub9cc \ub118\uae30\uba74 \uc544\uce68\uc5d0 \ub728\ub048\ud55c \uad6d \ud55c \uadf8\ub987\uc774\ub2e4.\u201d","\u201c\ub2e4\ub4e4 \ucd95 \ucc98\uc84c\uc5b4. \uc794\uce58 \ud55c\ubc88 \ud558\uc790, \uc1a5\uc740 \ub0b4\uac00 \uac78\uac8c.\u201d"],t.w)
B.aKf=new A.b(B.ee,["\u201c\uc7a5\uc791 \ubaa8\uc790\ub780\ub2e4. \ubaa9\uc7ac \uc880 \ubaa8\uc544 \uc640.\u201d","\u201c\uace0\ucca0 \ud544\uc694\ud558\ub2e4. \ub179\uc2a8 \uac83\ub3c4 \ub2e4 \uc4f4\ub2e4.\u201d","\u201c\ucc3d\uace0 \ube44\uc5b4 \uac04\ub2e4. \uba39\uc744 \uac70 \uc880 \ucc44\uc6cc \ub194.\u201d","\u201c\uc9c0\ubd95 \uad6c\uba4d \ub0ac\ub2e4. \ucca0\ud310\uc73c\ub85c \ub36e\uc790.\u201d","\u201c\ubc27\uc904 \ubaa8\uc790\ub780\ub2e4. \ub9dd\ub8e8 \uc62c\ub9ac\ub824\uba74 \ub354 \uaf2c\uc544\uc57c \ub3fc.\u201d","\u201c\uc800 \ub108\uba38 \uc9c0\ud615 \ubd10\uc57c\uaca0\ub2e4. \uc880 \ub354 \ubc1d\ud600.\u201d","\u201c\uc9c0\ub3c4\uc5d0 \ud45c\uc2dc\ud55c \ub370 \uc788\ub2e4. \ub204\uac00 \uac00\uc11c \ud655\uc778\ud558\uace0 \uc640.\u201d","\u201c\uc9c0\ud558 \uad6c\uc870 \ud55c\ubc88 \ubd10\uc57c\uaca0\ub2e4. \ub0b4\ub824\uac00 \ubcf4\uc790.\u201d","\u201c\ub77c\ub514\uc624\uc5d0 \ubb50 \uc7a1\ud78c\ub2e4. \ub2e4\uc774\uc5bc \ub3cc\ub824 \ubd10.\u201d","\u201c\ub2e4\ub4e4 \ubd80\ud0c1 \ud558\ub098\uc529\uc740 \uc788\ub2e4. \ud558\ub098\uc529 \ucc98\ub9ac\ud558\uc790.\u201d","\u201c\uc624\ub298 \ubc24 \ubc84\ud2f0\uc790. \ubc29\ubcbd\uc740 \ub0b4\uac00 \ubcf8\ub2e4.\u201d","\u201c\ub2e4\ub4e4 \uc9c0\ucce4\ub2e4. \uc794\uce58 \ud55c\ubc88 \ud558\uc790. \uacf5\uc0ac\ub294 \ud558\ub8e8 \uc270\ub2e4.\u201d"],t.w)
B.aKg=new A.b(B.ee,["\u201c\uc7a5\uc791\uc774 \ubaa8\uc790\ub77c\ub124. \uc624\ub298 \ubc24 \ubd88 \uc880 \ub109\ub109\ud788 \ud53c\uc6b0\uc138.\u201d","\u201c\uace0\ucca0\ub9cc \uc788\uc73c\uba74 \uc774\uac83\uc800\uac83 \uace0\uccd0 \ubcf4\uaca0\ub124.\u201d","\u201c\ucc3d\uace0\uac00 \ube44\uc5b4 \uac00\ub294\uad6c\uba3c. \uc544\uc774\ub4e4 \uba39\uc744 \uac70\ub77c\ub3c4 \ucc44\uc6cc \ub450\uac8c.\u201d","\u201c\uc9c0\ubd95\uc5d0 \uad6c\uba4d\uc774 \ub0ac\ub124. \ucca0\ud310\uc73c\ub85c \ub36e\uc5b4\uc57c\uaca0\ub124.\u201d","\u201c\ube68\ub7ab\uc904\uc774 \ub04a\uc5b4\uc84c\ub124. \ubc27\uc904 \uc880 \uaf2c\uc544 \uc8fc\uaca0\ub098?\u201d","\u201c\uc800 \ub108\uba38\uc5d0 \ubb50\uac00 \uc788\ub294\uc9c0 \uad81\uae08\ud558\uad6c\uba3c. \uc870\uae08\ub9cc \ub354 \ubc1d\ud600 \uc8fc\uac8c.\u201d","\u201c\uc9c0\ub3c4\uc5d0 \ud45c\uc2dc\ud574 \ub454 \uacf3\uc774 \uc788\ub124. \ub204\uac00 \ub2e4\ub140\uc640 \uc8fc\uaca0\ub098?\u201d","\u201c\uc9c0\ud558\uc5d0\uc11c \uc774\uc0c1\ud55c \uc18c\ub9ac\uac00 \ub0ac\ub2e4\ub354\uad70. \ud55c\ubc88 \ub0b4\ub824\uac00 \ubcf4\uac8c.\u201d","\u201c\ub77c\ub514\uc624\uc5d0\uc11c \ub204\uac00 \ubd80\ub974\ub294 \uac83 \uac19\uc558\ub124. \ub2e4\uc774\uc5bc \uc880 \ub3cc\ub824 \ubcf4\uac8c.\u201d","\u201c\ub2e4\ub4e4 \ub9d0\uc740 \uc548 \ud574\ub3c4 \ubd80\ud0c1\uc774 \ud558\ub098\uc529 \uc788\uc744 \uac78\uc138.\u201d","\u201c\uc624\ub298 \ubc24\ub3c4 \ubb34\uc0ac\ud788 \ub118\uae30\uc138. \uadf8\ub7fc \ucc28 \ud55c\uc794\ud558\uc138.\u201d","\u201c\uc694\uc998 \ub2e4\ub4e4 \uc9c0\ucce4\uad6c\uba3c. \uc794\uce58 \ud55c\ubc88 \uc5ec\uc138.\u201d"],t.w)
